const fs=require('fs');
const path=require('path');
const root=path.join(__dirname,'../..');
const migration=fs.readFileSync(path.join(root,'supabase/migrations/20260907065000_english_chatgpt_sprint_sets.sql'),'utf8');
const worker=fs.readFileSync(path.join(root,'supabase/functions/english-sprint-critic-worker/index.ts'),'utf8');
const landing=fs.readFileSync(path.join(root,'web-v2/components/chatgpt-sprint-sets.tsx'),'utf8');
const history=fs.readFileSync(path.join(root,'web-v2/components/sprint-report-history.tsx'),'utf8');
const page=fs.readFileSync(path.join(root,'web-v2/app/english/exam/page.tsx'),'utf8');
let bad=0;
const need=(s,x,m)=>s.includes(x)?console.log('✓ '+m):(bad++,console.error('✗ '+m));
const forbid=(s,x,m)=>!s.includes(x)?console.log('✓ '+m):(bad++,console.error('✗ '+m));
need(migration,'english.stage_chatgpt_sprint','ChatGPT staging owner exists');
need(migration,'sprint_self_critic_passes','ChatGPT self-critic is a hard gate');
need(migration,"status='critic_pending'",'Staged sets cannot start before Luna');
need(migration,"status='ready',set_no=v_set",'Set number is assigned only after final PASS');
need(migration,'Historical Sprint question repetition rejected','Historical exact replay is rejected');
need(migration,"Sprint creation now happens in ChatGPT",'Old app-side generation RPC is retired');
need(migration,"'*/10 * * * *'",'Luna transport retry safety-net is scheduled');
need(worker,'Audit the complete 25-question set together in ONE pass','Luna sees the full set together');
need(worker,'noWithinSetSemanticDuplicate','Luna checks semantic overlap');
need(worker,'noHistoricalRepeat','Luna checks historical freshness');
need(worker,'difficultyCalibration','Luna checks real difficulty calibration');
need(worker,'reasoning:{effort:"medium"}','Final Luna gate uses bounded medium reasoning');
need(landing,'Type <b>create sprint</b> in ChatGPT','App tells learner to create set in ChatGPT');
forbid(landing,'functions.invoke<SprintCreateResponse>("english-ssc-sprint"','New landing cannot call old generator');
need(page,'ChatgptSprintSets','Exam page uses ChatGPT set landing');
need(history,'Previous Sprint Sets','Completed tests are presented as set archive');
need(history,'p_days:3650','Archive is not limited to five days');
need(history,'label="Correct"','Review exposes Correct filter');
need(history,'label="Incorrect"','Review exposes Incorrect filter');
need(history,'label="Skipped"','Review exposes Skipped filter');
need(history,'← Previous','Question review has Previous navigation');
need(history,'Next →','Question review has Next navigation');
if(bad){console.error(`\nChatGPT Sprint set contracts failed with ${bad} defect(s).`);process.exit(1)}
console.log('\n✅ ChatGPT Sprint set contracts passed.');
